    "html.r3d_sub": "Acts on .nev clips, into an R3D NE folder next to each output, at the chosen compression and resolution. Log3G10 and REDWideGamutRGB. Always constant bitrate. Nikon ZR; Z8, Z9 and Z6III clips are <span class=\"badge-exp\">Experimental</span>.",
