    "html.beta": "<b>Beta software.</b> Keep your digital negatives (the original clips) until you have checked the compressed copies yourself.",
    "html.update_synology": "<b>Synology Container Manager:</b> open Project, select the Blue Compressor project and click Stop. Under Image, delete the old <code>ghcr.io/redn3/blue-compressor</code> image (or set the image tag in <code>docker-compose.yml</code> to <code id=\"update-banner-tag\">the new version</code>). Then build or start the project again; it downloads the new version.",
    "html.update_docker": "<b>Docker:</b> <code>docker pull ghcr.io/redn3/blue-compressor:latest</code>, then remove and recreate the container with the same settings.",
    "html.update_note": "Your settings, watch folders and compressed clips stay as they are. <a id=\"update-banner-link\" href=\"https://github.com/redn3/blue-compressor/releases/latest\" target=\"_blank\" rel=\"noopener\">What's new</a>. Set <code>UPDATE_CHECK=false</code> to turn these checks off.",
    "html.drop_sub": "Nikon N-RAW <span class=\"kbd\">.NEV</span> and R3D NE <span class=\"kbd\">.R3D</span>, any number at once",
