    "It has been tested on only a few cameras and clips. Do not delete your digital negatives (the original clips) until you have opened the compressed copies in your own software and checked them yourself.": "Det har bara testats med ett fåtal kameror och klipp. Radera inte dina digitala negativ (originalklippen) förrän du har öppnat de komprimerade kopiorna i ditt eget program och kontrollerat dem själv.",
