    "Every frame the same size in compressed clips (bpp targets; Lossless stays variable) and CBR proxies. Off: frames use what they need up to the target, proxies use quality based VBR. R3D NE is always constant; a rewrap is constant if the source is.": "Todos os quadros do mesmo tamanho nos clipes comprimidos (metas em bpp; Sem perdas continua variável) e proxies CBR. Desligado: os quadros usam o que precisam até a meta e os proxies usam VBR por qualidade. R3D NE é sempre constante; um reempacotamento é constante se a origem for.",
    "R3D NE and N-RAW": "R3D NE e N-RAW",
    "Rewrap only": "Só reempacotar",
    "No compressed copy: just the conversions below, with the image data copied as it is. About disk speed. Constant bitrate if the source is.": "Sem cópia comprimida: só as conversões abaixo, com os dados de imagem copiados como estão. Mais ou menos na velocidade do disco. Taxa constante se a origem for.",
    "N-RAW to R3D NE": "N-RAW para R3D NE",
    "R3D NE to N-RAW": "R3D NE para N-RAW",
    "Acts on .R3D clips: rewraps them back to N-RAW (N-LOG) in an N-RAW folder next to each output.": "Para clipes .R3D: reempacota de volta para N-RAW (N-LOG) em uma pasta N-RAW ao lado de cada saída.",
