    "Blue Compressor is beta software": "Blue Compressor é um software beta",
    "It has been tested on only a few cameras and clips. Do not delete your digital negatives (the original clips) until you have opened the compressed copies in your own software and checked them yourself.": "Foi testado com poucas câmeras e clipes. Não apague seus negativos digitais (os clipes originais) até abrir as cópias comprimidas no seu próprio software e conferi-las você mesmo.",
