    "Bitrate": "Bitrate",
    "Constant bitrate": "Bitrate costante",
    "Every frame the same size in compressed clips (bpp targets; Lossless stays variable) and CBR proxies. Off: frames use what they need up to the target, proxies use quality based VBR. R3D NE is always constant; a rewrap is constant if the source is.": "Ogni fotogramma della stessa dimensione nei clip compressi (obiettivi in bpp; Senza perdita resta variabile) e proxy CBR. Disattivato: i fotogrammi usano ciò che serve fino all'obiettivo, i proxy usano un VBR basato sulla qualità. R3D NE è sempre costante; una reincapsulazione è costante se lo è la sorgente.",
