    "Blue Compressor is beta software": "Blue Compressor è un software beta",
    "It has been tested on only a few cameras and clips. Do not delete your digital negatives (the original clips) until you have opened the compressed copies in your own software and checked them yourself.": "È stato provato solo con poche fotocamere e clip. Non eliminare i tuoi negativi digitali (i clip originali) finché non hai aperto le copie compresse nel tuo software e non le hai controllate tu stesso.",
