    "It has been tested on only a few cameras and clips. Do not delete your digital negatives (the original clips) until you have opened the compressed copies in your own software and checked them yourself.": "少数のカメラとクリップでしか試していません。圧縮コピーを自分のソフトで開いて確認するまで、デジタルネガ (元のクリップ) を削除しないでください。",
    "I understand": "了解",
    "Blue Compressor is available": "Blue Compressor が利用可能です",
    "Update now?": "今すぐ更新しますか?",
